import React from 'react';

const ClienteList = ({ clientes }) => {
  return (
    <div>
      <h3>Lista de Clientes</h3>
      <ul>
        {clientes.map((cliente) => (
          <li key={cliente.id}>
            {cliente.nome} - {cliente.email} - {cliente.telefone}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default ClienteList;
